def apply_top(nums, ops):
    b = nums.pop()
    a = nums.pop()
    op = ops.pop()
    if op == "+":
        nums.append(a + b)
    elif op == "-":
        nums.append(a - b)
    elif op == "*":
        nums.append(a * b)
    else:
        q = abs(a) // abs(b)
        nums.append(q if (a < 0) == (b < 0) else -q)

s = input()

prec = {"+": 1, "-": 1, "*": 2, "/": 2}
nums = []
ops = []
i = 0
while i < len(s):
    ch = s[i]
    if "0" <= ch <= "9":
        j = i
        while j < len(s) and "0" <= s[j] <= "9":
            j += 1
        nums.append(int(s[i:j]))
        i = j
        continue
    if ch == "(":
        ops.append(ch)
    elif ch == ")":
        while ops[-1] != "(":
            apply_top(nums, ops)
        ops.pop()
    elif ch in prec:
        while ops and ops[-1] != "(" and prec[ops[-1]] >= prec[ch]:
            apply_top(nums, ops)
        ops.append(ch)
    i += 1
while ops:
    apply_top(nums, ops)
print(nums[0])

